/// Best-effort manufacturer for [mac]; null when unknown or when the
/// address uses a private/randomized prefix.
String? manufacturerFor(String mac) {
  final hex = mac.replaceAll(RegExp(r'[^0-9A-Fa-f]'), '').toUpperCase();
  if (hex.length < 6) return null;
  // Locally-administered bit: set on privacy/randomized MAC addresses.
  if (int.parse(hex.substring(0, 2), radix: 16) & 0x02 != 0) return null;
  return ouiDb[hex.substring(0, 6)];
}
